@font-face {
  font-family: "Space Mono";
  src: url("assets/fonts/SpaceMono-Bold.ttf") format("truetype");
  font-weight: 700;
  font-display: swap;
}

:root {
  --bg: #05080a;
  --bg-2: #081014;
  --panel: #0a1114;
  --panel-2: #0d171b;
  --panel-3: #111f23;
  --ink: #edf7ee;
  --muted: #718486;
  --muted-2: #93a6a2;
  --line: rgba(201, 255, 61, 0.16);
  --line-soft: rgba(220, 255, 230, 0.1);
  --acid: #c9ff3d;
  --acid-bright: #dcff73;
  --corrupt: #ff4f63;
  --corrupt-deep: #4d111b;
  --safe: #43e6d3;
  --safe-deep: #062a2a;
  --amber: #ffd166;
  --display: "Archivo Black", Impact, "Arial Black", sans-serif;
  --mono: "Space Mono", ui-monospace, "Cascadia Mono", Consolas, monospace;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.5);
  --radius: 18px;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--mono);
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}

body {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 15% 10%, rgba(67, 230, 211, 0.07), transparent 38%),
    radial-gradient(ellipse at 88% 75%, rgba(255, 79, 99, 0.07), transparent 42%),
    radial-gradient(ellipse at 50% 110%, rgba(201, 255, 61, 0.05), transparent 45%),
    var(--bg);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(rgba(201, 255, 61, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(201, 255, 61, 0.035) 1px, transparent 1px);
  background-size: 52px 52px;
  mask-image: radial-gradient(ellipse at center, black 10%, transparent 75%);
  pointer-events: none;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 99;
  pointer-events: none;
  background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(0, 0, 0, 0.12) 3px 4px);
  opacity: 0.32;
  mix-blend-mode: multiply;
}

button { font: inherit; color: inherit; }
button:focus-visible { outline: 2px solid var(--acid); outline-offset: 4px; }
kbd {
  font-family: var(--mono);
  font-size: 9px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-bottom-color: rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  padding: 2px 5px;
  color: var(--muted-2);
  background: rgba(0, 0, 0, 0.28);
}
.is-hidden { display: none !important; }

.noise {
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

/* ---------- Game shell ---------- */

.shell {
  width: 100%;
  height: 100dvh;
  max-width: 1660px;
  margin: 0 auto;
  padding: max(12px, env(safe-area-inset-top)) clamp(12px, 1.8vw, 28px) max(10px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.topbar {
  min-height: 58px;
  display: flex;
  align-items: center;
  gap: clamp(14px, 2.4vw, 42px);
  flex: 0 0 auto;
  padding: 0 2px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 190px;
}
.brand-icon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--acid);
  border-radius: 9px;
  color: #071007;
  background: var(--acid);
  font-family: var(--mono);
  font-size: 25px;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 0 28px rgba(201, 255, 61, 0.2);
}
.brand-text { display: flex; flex-direction: column; gap: 2px; }
.brand-text strong {
  font-family: var(--display);
  font-size: 21px;
  letter-spacing: -0.03em;
  line-height: 1;
}
.brand-text strong span { color: var(--acid); }
.brand-text small {
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.sector-block, .score-block {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 42px;
  padding: 0 15px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(15, 24, 27, 0.9), rgba(8, 13, 15, 0.82));
}
.eyebrow {
  font-size: 8px;
  letter-spacing: 0.15em;
  color: var(--muted);
}
.sector-number { display: flex; align-items: baseline; gap: 2px; }
.sector-number b { font-size: 18px; color: var(--acid); }
.sector-number span { font-size: 10px; color: var(--muted); }
.sector-block em {
  font-style: normal;
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--muted-2);
  border-left: 1px solid var(--line-soft);
  padding-left: 11px;
}
.score-block { margin-left: auto; gap: 13px; }
.score-block strong {
  font-size: 18px;
  letter-spacing: 0.04em;
  color: var(--ink);
  min-width: 73px;
  text-align: right;
}
.top-actions { display: flex; gap: 7px; }
.icon-btn {
  width: 42px;
  height: 42px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: rgba(10, 17, 20, 0.85);
  color: var(--muted-2);
  cursor: pointer;
  display: grid;
  place-items: center;
  font-family: var(--mono);
  font-size: 14px;
  transition: 160ms ease;
}
.icon-btn:hover { border-color: var(--line); color: var(--acid); background: var(--panel-2); }
.sound-off { display: none; }
.is-muted .sound-on { display: none; }
.is-muted .sound-off { display: inline; }

.arena {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  border: 1px solid rgba(201, 255, 61, 0.18);
  border-radius: var(--radius);
  overflow: hidden;
  background:
    radial-gradient(ellipse at 25% 20%, rgba(67, 230, 211, 0.06), transparent 38%),
    radial-gradient(ellipse at 78% 82%, rgba(255, 79, 99, 0.055), transparent 42%),
    #060a0c;
  box-shadow: inset 0 0 90px rgba(0, 0, 0, 0.42), 0 18px 60px rgba(0, 0, 0, 0.25);
  cursor: crosshair;
  touch-action: none;
  user-select: none;
}
.arena::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    linear-gradient(90deg, rgba(201, 255, 61, 0.06), transparent 7%, transparent 93%, rgba(201, 255, 61, 0.06)),
    linear-gradient(0deg, rgba(201, 255, 61, 0.04), transparent 8%);
}
.arena::after {
  content: "";
  position: absolute;
  inset: 10px;
  z-index: 2;
  border: 1px dashed rgba(201, 255, 61, 0.1);
  border-radius: 11px;
  pointer-events: none;
}
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}
.vignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 48%, rgba(0, 0, 0, 0.5) 100%);
}

.hud {
  position: absolute;
  z-index: 8;
  top: 18px;
  left: 20px;
  right: 20px;
  display: grid;
  grid-template-columns: minmax(150px, 1fr) minmax(180px, 1.3fr) minmax(120px, 0.72fr);
  gap: 9px;
  pointer-events: none;
}
.hud-cell {
  height: 47px;
  padding: 8px 12px 9px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  background: rgba(5, 10, 12, 0.72);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.18);
}
.hud-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
  font-size: 8px;
  letter-spacing: 0.14em;
  color: var(--muted);
  text-transform: uppercase;
}
.hud-label b { color: var(--ink); font-size: 10px; letter-spacing: 0.03em; }
.meter {
  height: 3px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09);
  overflow: hidden;
}
.meter i {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: var(--acid);
  box-shadow: 0 0 10px rgba(201, 255, 61, 0.4);
  transition: width 120ms linear, background 240ms ease;
}
.integrity-cell .meter i { background: var(--safe); box-shadow: 0 0 10px rgba(67, 230, 211, 0.35); }
.time-cell .meter i { background: var(--acid); }
.integrity-cell.is-low .meter i { background: var(--corrupt); box-shadow: 0 0 12px rgba(255, 79, 99, 0.6); }
.integrity-cell.is-low .hud-label b { color: var(--corrupt); }
.time-cell.is-low .meter i { background: var(--corrupt); }
.time-cell.is-low .hud-label b { color: var(--corrupt); }

.arena-tag {
  position: absolute;
  z-index: 5;
  left: 24px;
  bottom: 22px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 7px;
  letter-spacing: 0.15em;
  color: rgba(147, 166, 162, 0.5);
  pointer-events: none;
}
.live-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--corrupt);
  box-shadow: 0 0 8px rgba(255, 79, 99, 0.8);
  animation: blink 1.35s steps(1) infinite;
}
@keyframes blink { 50% { opacity: 0.22; } }

.hint {
  position: absolute;
  z-index: 5;
  left: 24px;
  bottom: 42px;
  color: rgba(147, 166, 162, 0.62);
  font-size: 8px;
  letter-spacing: 0.12em;
  pointer-events: none;
  transition: opacity 500ms ease;
}
.mobile-hint { display: none; }
.hint.is-faded { opacity: 0; }

.nuke {
  position: absolute;
  z-index: 12;
  right: 22px;
  bottom: 18px;
  width: 190px;
  height: 66px;
  padding: 11px 14px 12px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  background: rgba(9, 15, 17, 0.9);
  color: var(--muted);
  text-align: left;
  cursor: not-allowed;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: 180ms ease;
}
.nuke-top { display: flex; align-items: center; gap: 8px; }
.nuke-spark { font-size: 15px; line-height: 1; color: rgba(255, 255, 255, 0.25); }
.nuke b { font-family: var(--display); font-size: 15px; letter-spacing: 0.01em; }
.nuke-sub { display: flex; align-items: center; justify-content: space-between; margin-top: 4px; font-size: 8px; letter-spacing: 0.11em; }
.nuke-sub kbd { opacity: 0.6; }
.nuke-charge {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0%;
  height: 3px;
  background: var(--safe);
  box-shadow: 0 0 12px var(--safe);
  transition: width 100ms linear;
}
.nuke:not(:disabled) {
  color: #071007;
  border-color: var(--acid);
  background: linear-gradient(105deg, var(--acid), #a5ee29);
  cursor: pointer;
  box-shadow: 0 0 0 1px rgba(201, 255, 61, 0.2), 0 0 34px rgba(201, 255, 61, 0.22);
  animation: nuke-ready 1.8s ease-in-out infinite;
}
.nuke:not(:disabled) .nuke-spark,
.nuke:not(:disabled) .nuke-sub { color: rgba(7, 16, 7, 0.65); }
.nuke:not(:disabled) .nuke-charge { background: rgba(7, 16, 7, 0.55); box-shadow: none; width: 100% !important; }
.nuke:not(:disabled):hover { transform: translateY(-2px); filter: brightness(1.06); }
.nuke:not(:disabled):active { transform: translateY(0) scale(0.985); }
@keyframes nuke-ready { 50% { box-shadow: 0 0 0 1px rgba(201, 255, 61, 0.24), 0 0 48px rgba(201, 255, 61, 0.38); } }

.nuke-fx {
  position: absolute;
  z-index: 30;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  pointer-events: none;
  opacity: 0;
  color: var(--acid);
  text-align: center;
}
.nuke-fx span {
  font-family: var(--display);
  font-size: clamp(38px, 8vw, 96px);
  letter-spacing: -0.04em;
  line-height: 1;
  text-shadow: 0 0 36px rgba(201, 255, 61, 0.5), 5px 0 var(--corrupt), -5px 0 var(--safe);
}
.nuke-fx small { font-size: 9px; letter-spacing: 0.38em; color: var(--ink); }
.nuke-fx.fire { animation: nuke-flash 720ms ease-out both; }
@keyframes nuke-flash {
  0% { opacity: 0; transform: scale(1.25); filter: blur(5px); }
  12% { opacity: 1; transform: scale(1); filter: blur(0); }
  55% { opacity: 1; }
  100% { opacity: 0; transform: scale(0.97); }
}

.toasts {
  position: absolute;
  z-index: 20;
  left: 50%;
  top: 25%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  width: min(88%, 600px);
  pointer-events: none;
  text-align: center;
}
.toast {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
  padding: 7px 12px;
  border: 1px solid rgba(201, 255, 61, 0.24);
  border-radius: 4px;
  background: rgba(5, 10, 11, 0.86);
  color: var(--acid);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
  animation: toast-in 220ms ease-out both;
}
.toast.danger { border-color: rgba(255, 79, 99, 0.42); color: var(--corrupt); }
.toast.safe { border-color: rgba(67, 230, 211, 0.3); color: var(--safe); }
.toast.gold { border-color: rgba(255, 209, 102, 0.4); color: var(--amber); }
.toast.big { padding: 10px 18px; font-family: var(--display); font-size: 17px; letter-spacing: 0.02em; }
.toast.out { animation: toast-out 300ms ease-in both; }
@keyframes toast-in { from { opacity: 0; transform: translateY(-8px) scale(0.96); } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-8px); } }

.footerbar {
  flex: 0 0 auto;
  min-height: 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 3px;
}
.legend { display: flex; align-items: center; gap: 22px; }
.legend span { display: flex; align-items: center; gap: 6px; font-size: 8px; letter-spacing: 0.12em; color: var(--muted); }
.legend b { color: var(--muted-2); }
.dot { width: 6px; height: 6px; border-radius: 1px; display: inline-block; }
.dot.corrupt { background: var(--corrupt); box-shadow: 0 0 8px rgba(255, 79, 99, 0.6); }
.dot.safe { background: var(--safe); box-shadow: 0 0 8px rgba(67, 230, 211, 0.5); }
.chain { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 8px; letter-spacing: 0.14em; }
.chain b { font-size: 14px; color: var(--muted-2); min-width: 30px; }
.chain i { display: block; width: 86px; height: 3px; border-radius: 9px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.chain u { display: block; height: 100%; width: 0%; background: var(--amber); text-decoration: none; }
.chain.active { color: var(--amber); }
.chain.active b { color: var(--amber); text-shadow: 0 0 14px rgba(255, 209, 102, 0.5); }

/* ---------- Menu ---------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 50;
}
.menu {
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: auto;
  padding: clamp(24px, 5vh, 64px) clamp(20px, 4.5vw, 76px) 58px;
  background:
    radial-gradient(ellipse at 77% 43%, rgba(201, 255, 61, 0.06), transparent 30%),
    radial-gradient(ellipse at 18% 18%, rgba(67, 230, 211, 0.06), transparent 34%),
    radial-gradient(ellipse at 22% 90%, rgba(255, 79, 99, 0.055), transparent 38%),
    rgba(4, 7, 9, 0.92);
  backdrop-filter: blur(2px);
}
.menu::before {
  content: "rm -rf /";
  position: absolute;
  right: -3vw;
  bottom: 4vh;
  z-index: -1;
  font-family: var(--display);
  font-size: clamp(110px, 22vw, 360px);
  letter-spacing: -0.08em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(201, 255, 61, 0.055);
  white-space: nowrap;
  transform: rotate(-4deg);
  pointer-events: none;
}
.menu::after {
  content: "";
  position: absolute;
  inset: 18px;
  z-index: -1;
  border: 1px solid rgba(201, 255, 61, 0.09);
  pointer-events: none;
}
.menu-grid {
  width: min(1450px, 100%);
  margin: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(330px, 0.6fr);
  align-items: center;
  gap: clamp(36px, 6vw, 100px);
}
.hero { max-width: 850px; }
.hero-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: clamp(18px, 3vh, 36px);
  color: var(--corrupt);
  font-size: 9px;
  letter-spacing: 0.22em;
  font-weight: 700;
}
.kicker-code { margin-left: 4px; color: var(--muted); letter-spacing: 0.08em; }
.logo {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(72px, 12.5vw, 198px);
  line-height: 0.76;
  letter-spacing: -0.065em;
  text-transform: uppercase;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  user-select: none;
}
.logo-delete { color: var(--ink); text-shadow: 0 18px 60px rgba(0, 0, 0, 0.45); }
.logo-all {
  position: relative;
  color: var(--acid);
  text-shadow: 0 0 70px rgba(201, 255, 61, 0.18);
  padding-right: 0.04em;
}
.logo-all::before,
.logo-all::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
}
.logo-all:hover::before { opacity: 0.55; color: var(--corrupt); transform: translate(5px, -2px); clip-path: inset(18% 0 55% 0); animation: glitch 1.2s steps(2) infinite; }
.logo-all:hover::after { opacity: 0.55; color: var(--safe); transform: translate(-5px, 2px); clip-path: inset(64% 0 14% 0); animation: glitch 1.4s steps(2) infinite reverse; }
@keyframes glitch { 25% { transform: translate(4px, -1px); } 50% { transform: translate(-3px, 2px); } 75% { transform: translate(2px, -2px); } }
.logo-blink { color: var(--corrupt); margin-left: 0.03em; animation: blink 1s steps(1) infinite; }
.tagline {
  margin: clamp(22px, 3.6vh, 38px) 0 0;
  font-family: var(--mono);
  font-size: clamp(13px, 1.4vw, 17px);
  line-height: 1.65;
  letter-spacing: 0.01em;
  color: var(--muted-2);
}
.tagline strong { color: var(--ink); font-weight: 700; }
.menu-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: clamp(24px, 4vh, 42px); }
.btn {
  min-height: 51px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: 5px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
  transition: 170ms ease;
}
