+    return { corrupt, safe };
+  }
+
+  function handleBox(rect) {
+    const inside = selectionContents(rect);
+    const center = { x: (rect.x1 + rect.x2) / 2, y: (rect.y1 + rect.y2) / 2 };
+    G.selectionPreview = null;
