+      sound.tick();
+      return;
+    }
+    if (hit.corrupt) applyTargets([hit], [], { x: hit.x + hit.w / 2, y: hit.y + hit.h / 2 });
+    else applyTargets([], [hit], { x: hit.x + hit.w / 2, y: hit.y + hit.h / 2 });
